import sys
import os

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    path = sys.argv[1]
    basename = os.path.basename(path)

    # Remove the last extension only
    # Find the last dot that's not at position 0
    dot_index = -1
    for i in range(len(basename) - 1, -1, -1):
        if basename[i] == '.':
            dot_index = i
            break

    if dot_index > 0:
        result = basename[:dot_index]
    else:
        result = basename

    print(result)

if __name__ == "__main__":
    main()

