import sys

# Find the setuptools version by reading its metadata without importing it.
version = None

# Strategy: locate site-packages directories from sys.path and look for
# setuptools-* .dist-info or egg-info directories containing a VERSION file.
import os

def find_setuptools_version():
    global version
    search_dirs = []
    for p in sys.path:
        if p:
            search_dirs.append(p)
            # also check common subdirs like site-packages
            sp = os.path.join(p, "site-packages")
            if os.path.isdir(sp):
                search_dirs.append(sp)

    seen = set()
    for d in search_dirs:
        if not os.path.isdir(d):
            continue
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for e in entries:
            full = os.path.join(d, e)
            if not os.path.isdir(full):
                continue
            # Match setuptools-x.y.z.dist-info or setuptools-x.y.z-py?.egg-info
            if not e.startswith("setuptools-"):
                continue
            # Try .dist-info first
            dist_info = e + ".dist-info"
            di_path = os.path.join(d, dist_info)
            if os.path.isdir(di_path):
                # Read METADATA file to get Version: line
                metadata_path = os.path.join(di_path, "METADATA")
                if os.path.isfile(metadata_path):
                    try:
                        with open(metadata_path, "r") as f:
                            for line in f:
                                if line.startswith("Version:"):
                                    v = line.split(":", 1)[1].strip()
                                    return v
                    except Exception:
                        pass
                # Fallback: read VERSION file if present
                ver_path = os.path.join(di_path, "VERSION")
                if os.path.isfile(ver_path):
                    try:
                        with open(ver_path, "r") as f:
                            return f.read().strip()
                    except Exception:
                        pass
            # Try egg-info
            # egg-info dir name is like setuptools-44.1.1-py3.7.egg-info
            # We need to find a directory that starts with e + "-py" or just e + ".egg-info"
            # Actually the dir name already is the full name; we just need to check if it ends with .egg-info
            if e.endswith(".egg-info"):
                pass  # handled below when iterating
            # Check for egg-info subdirectory pattern
            for e2 in entries:
                full2 = os.path.join(d, e2)
                if not os.path.isdir(full2):
                    continue
                if e2.startswith("setuptools-") and e2.endswith(".egg-info"):
                    ver_path = os.path.join(full2, "VERSION")
                    if os.path.isfile(ver_path):
                        try:
                            with open(ver_path, "r") as f:
                                return f.read().strip()
                        except Exception:
                            pass

    return None

v = find_setuptools_version()
if v is not None:
    print('system setuptools', v)
else:
    # Fallback: try to get version from a known location or raise
    sys.exit(1)

