def _shorten(s, width):
    words = s.split()
    result_words = []
    current_len = 0
    for word in words:
        # Calculate the length if we add this word
        if not result_words:
            new_len = len(word)
        else:
            new_len = current_len + 1 + len(word)

        if new_len <= width:
            result_words.append(word)
            current_len = new_len
        else:
            break

    # If we didn't include all words, we need to shorten
    if len(result_words) < len(words):
        if not result_words:
            # The first word itself is too long
            if len(words[0]) > width:
                return words[0][:width-1] + '…'
            else:
                return words[0] + '…'
        else:
            # We have some words, need to trim the last one to fit with ellipsis
            # Current length of result_words joined
            current_str = ' '.join(result_words)
            remaining_space = width - len(current_str) - 1  # -1 for the space before ellipsis? No...

            # Actually, let's think again.
            # We want: "word1 word2 ... lastword…" where total length <= width
            # If we keep all result_words as is, their joined length is current_len.
            # We need to add an ellipsis '…' (length 1) at the end.
            # So total would be current_len + 1.
            # If current_len + 1 <= width, we can just append '…'
            if current_len + 1 <= width:
                return current_str + '…'
            else:
                # We need to trim the last word
                last_word = result_words[-1]
                # How much space do we have for the last word + ellipsis?
                # Previous words length:
                if len(result_words) > 1:
                    prev_len = len(' '.join(result_words[:-1])) + 1  # +1 for space
                else:
                    prev_len = 0

                available_for_last = width - prev_len - 1  # -1 for ellipsis
                if available_for_last < 1:
                    # Can't even fit one char + ellipsis, so we might need to remove more words
                    # But since we're building greedily, this shouldn't happen if we check properly
                    # Let's just take what we can
                    trimmed = last_word[:max(0, available_for_last)]
                    return ' '.join(result_words[:-1] + [trimmed + '…']) if result_words[:-1] else trimmed + '…'
                else:
                    trimmed = last_word[:available_for_last]
                    return ' '.join(result_words[:-1] + [trimmed + '…']) if result_words[:-1] else trimmed + '…'
    else:
        return s

print(_shorten("a very long sentence indeed here", width=20))

