import os

# Compute the set of standard library module names without using sys.stdlib_module_names.
# We replicate the logic: top-level modules in the stdlib (not submodules, not dunder),
# then sort and print count + space-joined list.

def get_stdlib_modules():
    # Find all standard library directories
    # sys.path is not needed; we use known stdlib locations via os
    import sys as _sys
    paths = _sys.path
    stdlib_dirs = set()
    for p in paths:
        if p and os.path.isdir(p):
            stdlib_dirs.add(os.path.realpath(p))

    names = set()
    for d in stdlib_dirs:
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for e in entries:
            if e.startswith('_'):
                continue
            full = os.path.join(d, e)
            if os.path.isfile(full) and e.endswith('.py'):
                modname = e[:-3]
                names.add(modname)
            elif os.path.isdir(full):
                # A package directory; include if it has __init__.py or is a namespace pkg?
                # For stdlib_module_names, packages with __init__.py are included.
                init = os.path.join(full, '__init__.py')
                if os.path.isfile(init):
                    names.add(e)

    return sorted(names)

