def _dedent(text):
    if not text:
        return text
    lines = text.split('\n')
    margins = []
    for line in lines:
        stripped = len(line) - len(line.lstrip(' '))
        if stripped < len(line):
            margins.append(stripped)
    if not margins:
        return text
    margin = min(margins)
    result = []
    for line in lines:
        if line.startswith(' ' * margin):
            result.append(line[margin:])
        else:
            result.append(line)
    return '\n'.join(result)


