def dedent(text):
    lines = text.splitlines(True)
    margin = None
    for line in lines:
        stripped = line.lstrip(' ')
        indent = len(line) - len(stripped)
        if stripped:
            if margin is None:
                margin = indent
            else:
                margin = min(margin, indent)
    if margin:
        return [line[margin:] if len(line) >= margin else '' for line in lines]
    return lines

