import sys

cp = "{1, 2}\n{'c', 'a', 'b'}\n"
mp = "{2, 1}\n{'c', 'b', 'a'}\n"

def only_set_order_differs(cp, mp):
    # Determine if the two strings differ only in the order of elements within sets/dicts
    lines_cp = cp.split('\n')
    lines_mp = mp.split('\n')

    if len(lines_cp) != len(lines_mp):
        return False

    for line_c, line_m in zip(lines_cp, lines_mp):
        # Try to parse as set/dict representation
        def parse_collection(s):
            s = s.strip()
            if not s:
                return None
            if s.startswith('{') and s.endswith('}'):
                inner = s[1:-1]
                if not inner.strip():
                    return set()
                items = []
                depth = 0
                current = ''
                in_str = False
                str_char = None
                i = 0
                while i < len(inner):
                    ch = inner[i]
                    if in_str:
                        current += ch
                        if ch == str_char:
                            in_str = False
                    else:
                        if ch in ('"', "'"):
                            in_str = True
                            str_char = ch
                            current += ch
                        elif ch == '{':
                            depth += 1
                            if depth == 1:
                                if current.strip():
                                    items.append(current.strip())
                                current = ''
                            else:
                                current += ch
                        elif ch == '}':
                            depth -= 1
                            if depth == 0:
                                if current.strip():
                                    items.append(current.strip())
                                current = ''
                            else:
                                current += ch
                        elif ch == ',' and depth == 0:
                            if current.strip():
                                items.append(current.strip())
                            current = ''
                        else:
                            current += ch
                    i += 1
                if current.strip():
                    items.append(current.strip())
                return items
            return None

        items_c = parse_collection(line_c)
        items_m = parse_collection(line_m)

        if items_c is not None and items_m is not None:
            if sorted(items_c) != sorted(items_m):
                return False
        else:
            if line_c != line_m:
                return False

    return True

print('corpus py-e6d1774f843c ->', only_set_order_differs(cp, mp))
print('probe                 ->', only_set_order_differs('{1, 2, 3}\n', '{3, 1, 2}\n'))
sys.exit(0)

