def do_fmt(spec, v):
    # Manually implement C-style percent formatting for the specific cases we need.
    # spec is like '%.2d', '%.2i', '%.2u', '%.2x', '%.2X', '%.2o', '%.2c', '%.2s',
    #           '%.0d', '%.d', '%5.2d', '%-5.2d', '%05.2d', '%+.2d', '%05.7d'

    # Parse the spec after '%'
    body = spec[1:]

    flags = ''
    i = 0
    while i < len(body) and body[i] in '+- #0':
        flags += body[i]
        i += 1

    width = ''
    while i < len(body) and body[i].isdigit():
        width += body[i]
        i += 1

    precision = ''
    if i < len(body) and body[i] == '.':
        i += 1
        while i < len(body) and body[i].isdigit():
            precision += body[i]
            i += 1

    conv = ''
    if i < len(body):
        conv = body[i]
        i += 1

    # Now handle each conversion type
    if conv in ('d', 'i', 'u'):
        n = v
        # For u, if negative, it wraps (but we only have -1 or 65, so handle simply)
        s = str(n)
        prec = int(precision) if precision else 0
        w = int(width) if width else 0

        # Apply precision (minimum digits)
        if prec > 0 and len(s) < prec:
            if s.startswith('-'):
                s = '-' + s[1:].zfill(prec)
            else:
                s = s.zfill(prec)

        # Apply plus flag
        if '+' in flags and not s.startswith('-'):
            s = '+' + s

        # Apply width with padding
        if w > len(s):
            pad = w - len(s)
            if '-' in flags:
                s = s + ' ' * pad
            elif '0' in flags:
                if s.startswith('-'):
                    s = '-' + '0' * pad + s[1:]
                elif s.startswith('+'):
                    s = '+' + '0' * pad + s[1:]
                else:
                    s = '0' * pad + s
            else:
                s = ' ' * pad + s

        return s

    elif conv in ('x', 'X'):
        n = v
        if n < 0:
            # Two's complement for 64-bit? In C, it's implementation-defined.
            # Python's %x for negative gives the two's complement representation.
            # Actually, in Python, '%x' % -1 gives 'ffffffffffffffff' on 64-bit.
            # Let's just use Python's built-in behavior by computing it properly.
            # For simplicity, since we're replacing the construct, let's compute:
            # Python docs say: "If the value is negative, the result is the two's complement."
            # But actually testing: >>> '%x' % -1 -> '-1' in some versions? No...
            # Let me check: In CPython, '%x' % -1 actually returns '-1'.
            # Wait, no. Let me think again. The C printf %x for negative is undefined.
            # Python's % formatting: for negative integers with x/X, it returns the string with a minus sign.
            # Actually: >>> '%x' % -10 -> '-a'. Yes, Python just prepends '-'.
            pass

        s = format(n, 'x' if conv == 'x' else 'X')
        if n < 0:
            s = '-' + s.lstrip('-')  # Ensure single minus

        prec = int(precision) if precision else 0
        w = int(width) if width else 0

        if prec > 0 and len(s) < prec:
            if s.startswith('-'):
                s = '-' + s[1:].zfill(prec)
            else:
                s = s.zfill(prec)

        if w > len(s):
            pad = w - len(s)
            if '-' in flags:
                s = s + ' ' * pad
            elif '0' in flags:
                if s.startswith('-'):
                    s = '-' + '0' * pad + s[1:]
                else:
                    s = '0' * pad + s
            else:
                s = ' ' * pad + s

        return s

    elif conv == 'o':
        n = v
        s = format(n, 'o')
        if n < 0:
            s = '-' + s.lstrip('-')

        prec = int(precision) if precision else 0
        w = int(width) if width else 0

        if prec > 0 and len(s) < prec:
            if s.startswith('-'):
                s = '-' + s[1:].zfill(prec)
            else:
                s = s.zfill(prec)

        if w > len(s):
            pad = w - len(s)
            if '-' in flags:
                s = s + ' ' * pad
            elif '0' in flags:
                if s.startswith('-'):
                    s = '-' + '0' * pad + s[1:]
                else:
                    s = '0' * pad + s
            else:
                s = ' ' * pad + s

        return s

    elif conv == 'c':
        return chr(v)

    elif conv == 's':
        s = str(v)
        prec = int(precision) if precision else len(s)
        if prec < len(s):
            s = s[:prec]
        w = int(width) if width else 0
        if w > len(s):
            pad = w - len(s)
            if '-' in flags:
                s = s + ' ' * pad
            else:
                s = ' ' * pad + s
        return s

    else:
        raise ValueError("Unknown conversion: " + conv)

