import sys

def _percent_format(fmt, args):
    """Minimal implementation of Python's % operator for a single format spec."""
    # args may be a single value or a tuple
    if not isinstance(args, tuple):
        args = (args,)
    out = []
    i = 0
    n = len(fmt)
    while i < n:
        c = fmt[i]
        if c == '%':
            i += 1
            if i >= n:
                raise ValueError("incomplete format")
            c2 = fmt[i]
            if c2 == '%':
                out.append('%')
                i += 1
                continue
            # parse conversion flags
            j = i
            flags = set()
            while j < n and fmt[j] in '+-# 0':
                flags.add(fmt[j])
                j += 1
            width = None
            if j < n and fmt[j].isdigit():
                k = j
                while k < n and fmt[k].isdigit():
                    k += 1
                width = int(fmt[j:k])
                j = k
            precision = None
            if j < n and fmt[j] == '.':
                j += 1
                if j < n and fmt[j].isdigit():
                    k = j
                    while k < n and fmt[k].isdigit():
                        k += 1
                    precision = int(fmt[j:k])
                    j = k
                else:
                    precision = 0
            # length modifier (ignored for our purposes)
            if j < n and fmt[j] in 'hlL':
                j += 1
            if j >= n:
                raise ValueError("incomplete format")
            conv = fmt[j]
            i = j + 1
            # get the next argument
            if not args:
                raise TypeError("not enough arguments for format string")
            val = args[0]
            args = args[1:]
            s = _convert(conv, val, flags, width, precision)
            out.append(s)
        else:
            out.append(c)
            i += 1
    return ''.join(out)


def _convert(conv, val, flags, width, precision):
    if conv == 'd' or conv == 'i':
        if isinstance(val, bool):
            v = int(val)
        elif isinstance(val, int):
            v = val
        else:
            raise TypeError("unsupported type")
        s = _format_int(v, flags, width, precision)
        return s
    elif conv == 'u':
        if isinstance(val, bool):
            v = int(val)
        elif isinstance(val, int):
            v = val
        else:
            raise TypeError("unsupported type")
        if v < 0:
            v = v + (1 << 64)  # wrap to unsigned 64-bit
        s = _format_int(v, flags, width, precision)
        return s
    elif conv == 'x':
        if isinstance(val, bool):
            v = int(val)
        elif isinstance(val, int):
            v = val
        else:
            raise TypeError("unsupported type")
        return _format_hex(v, 'x', flags, width, precision)
    elif conv == 'X':
        if isinstance(val, bool):
            v = int(val)
        elif isinstance(val, int):
            v = val
        else:
            raise TypeError("unsupported type")
        return _format_hex(v, 'X', flags, width, precision)
    elif conv == 'o':
        if isinstance(val, bool):
            v = int(val)
        elif isinstance(val, int):
            v = val
        else:
            raise TypeError("unsupported type")
        if v < 0:
            sign = '-'
            v = -v
        else:
            sign = ''
        body = format(v, 'o')
        if precision is not None:
            body = body.zfill(precision)
        result = sign + body
        if width is not None and len(result) < width:
            if '0' in flags and not ('-' in flags):
                fill = '0' * (width - len(result))
                if sign and result[0] == '-':
                    result = '-' + fill + body
                else:
                    result = fill + result
            else:
                if '-' in flags:
                    result = result.ljust(width)
                else:
                    result = result.rjust(width)
        return result
    elif conv == 'c':
        if isinstance(val, str) and len(val) == 1:
            ch = val
        elif isinstance(val, int):
            ch = chr(val)
        else:
            raise TypeError("unsupported type")
        s = ch
        if width is not None and len(s) < width:
            if '0' in flags and not ('-' in flags):
                s = '0' * (width - len(s)) + s
            elif '-' in flags:
                s = s.ljust(width)
            else:
                s = s.rjust(width)
        return s
    elif conv == 's':
        if isinstance(val, str):
            s = val
        elif isinstance(val, bytes):
            s = val.decode('utf-8', errors='replace')
        else:
            s = str(val)
        if precision is not None:
            s = s[:precision]
        if width is not None and len(s) < width:
            if '-' in flags:
                s = s.ljust(width)
            else:
                s = s.rjust(width)
        return s
    else:
        raise ValueError("unsupported conversion character %r" % conv)


def _format_int(v, flags, width, precision):
    if v < 0:
        sign = '-'
        body = format(-v, 'd')
    else:
        if '+' in flags:
            sign = '+'
        else:
            sign = ''
        body = format(v, 'd')
    if precision is not None:
        body = body.zfill(precision)
    result = sign + body
    if width is not None and len(result) < width:
        if '0' in flags and not ('-' in flags):
            fill = '0' * (width - len(result))
            if sign and result[0] in ('+', '-'):
                result = result[0] + fill + body
            else:
                result = fill + result
        else:
            if '-' in flags:
                result = result.ljust(width)
            else:
                result = result.rjust(width)
    return result


def _format_hex(v, case, flags, width, precision):
    if v < 0:
        sign = '-'
        body = format(-v, case)
    else:
        sign = ''
        body = format(v, case)
    if '#' in flags and body != '0':
        prefix = '0' + case
        body = prefix + body
    if precision is not None:
        body = body.zfill(precision)
    result = sign + body
    if width is not None and len(result) < width:
        if '0' in flags and not ('-' in flags):
            fill = '0' * (width - len(result))
            if sign and result[0] == '-':
                result = '-' + fill + body
            else:
                result = fill + result
        else:
            if '-' in flags:
                result = result.ljust(width)
            else:
                result = result.rjust(width)
    return result


