# Reproduce the same output without using integer precision in % formatting.
# For each format string, compute the result by hand (equivalent semantics) and
# emit the same line as the original program.

def fmt(s, v):
    # returns the string that `s % v` would produce, or raises the same exception
    # We only need to handle the specific cases in the list.
    spec = s[1:]  # without leading '%'
    # Parse: optional flags, optional width, optional .precision, conversion char
    i = 0
    flags = ''
    while i < len(spec) and spec[i] in '+- #0':
        flags += spec[i]
        i += 1
    width = None
    while i < len(spec) and spec[i].isdigit():
        width = spec[i] if width is None else width + spec[i]
        i += 1
    if width is not None:
        width = int(width)
    prec = None
    if i < len(spec) and spec[i] == '.':
        i += 1
        p = ''
        while i < len(spec) and spec[i].isdigit():
            p += spec[i]
