import sys

def fmt(spec, value):
    """Manually implement %-formatting for the specific cases we need."""
    # spec is like '%.2d', '%5.2d', etc.
    # Parse: optional sign flag (+), optional zero flag (0), width, .precision, conversion
    s = spec[1:]  # strip leading %

    # Determine conversion type (last char)
    conv = s[-1]
    body = s[:-1]

    # Parse flags and numbers from body
    flags = set()
    width = None
    precision = None

    i = 0
    while i < len(body):
        c = body[i]
        if c == '+':
            flags.add('+')
            i += 1
        elif c == '-':
            flags.add('-')
            i += 1
        elif c == '0':
            flags.add('0')
            i += 1
        elif c == '.':
            i += 1
            num = ''
            while i < len(body) and body[i].isdigit():
                num += body[i]
                i += 1
            precision = int(num) if num else None
        else:
            if c.isdigit():
                num = ''
                while i < len(body) and body[i].isdigit():
                    num += body[i]
                    i += 1
                width = int(num)
            else:
                i += 1

    # Now format based on conversion type
    if conv in ('d', 'i', 'u'):
        # Integer conversion
        v = int(value)
        negative = v < 0
        av = abs(v)

        # Convert to string
        digits = str(av)

        # Apply precision (minimum number of digits)
        if precision is not None and precision > len(digits):
            digits = '0' * (precision - len(digits)) + digits

        # Add sign
        if negative:
            sign = '-'
        elif '+' in flags:
            sign = '+'
        else:
            sign = ''

        result = sign + digits

        # Apply width
        if width is not None and len(result) < width:
            padding = width - len(result)
            if '-' in flags:
                result = result + ' ' * padding
            elif '0' in flags and sign:
                result = sign + '0' * padding + digits
            else:
                result = ' ' * padding + result

        return result

    elif conv in ('x', 'X'):
        v = int(value)
        if v < 0:
            # Negative hex - Python formats as -0x...
            digits = format(-v, 'x' if conv == 'x' else 'X')
            result = '-' + digits
        else:
            result = format(v, 'x' if conv == 'x' else 'X')

        if precision is not None and precision > len(result):
            result = '0' * (precision - len(result)) + result

        if width is not None and len(result) < width:
            padding = width - len(result)
            if '-' in flags:
                result = result + ' ' * padding
            elif '0' in flags:
                result = '0' * padding + result
            else:
                result = ' ' * padding + result

        return result

    elif conv == 'o':
        v = int(value)
        if v < 0:
            digits = format(-v, 'o')
            result = '-' + digits
        else:
            result = format(v, 'o')

        if precision is not None and precision > len(result):
            result = '0' * (precision - len(result)) + result

        if width is not None and len(result) < width:
            padding = width - len(result)
            if '-' in flags:
                result = result + ' ' * padding
            elif '0' in flags:
                result = '0' * padding + result
            else:
                result = ' ' * padding + result

        return result

    elif conv == 'c':
        return chr(int(value))

    elif conv == 's':
        sv = str(value)
        if precision is not None:
            sv = sv[:precision]
        if width is not None and len(sv) < width:
            padding = width - len(sv)
            if '-' in flags:
                sv = sv + ' ' * padding
            else:
                sv = ' ' * padding + sv
        return sv

    return str(value)

