import sys

# We need to reproduce the output of:
#   for s in [...]:
#       v = ...
#       try: r = repr(s % v)
#       except Exception as e: r = '%s: %s' % (type(e).__name__, str(e)[:40])
#       print('  %-8s %% %-4r -> %s' % (s, v, r))
#
# The runtime refuses '%.2d' style (precision on integer conversion).
# So we must avoid using % with a precision spec on d/i/u/x/X/o conversions.
# But we still need to compute the same values.
# 
# Strategy: implement our own format function that handles all these cases,
# producing the exact same string as Python's % operator would.

def format_value(fmt, v):
    """Simulate fmt % v for the specific formats in our list."""
    # Parse the format string
    if not fmt.startswith('%'):
        raise ValueError("bad format")

    body = fmt[1:]

    # Determine fields: flags, width, precision, conversion
    i = 0
    flags = ''
    while i < len(body) and body[i] in '+-# 0':
        flags += body[i]
        i += 1

    width = None
    if i < len(body) and body[i].isdigit():
        j = i
        while j < len(body) and body[j].isdigit():
            j += 1
        width = int(body[i:j])
        i = j

    precision = None
    if i < len(body) and body[i] == '.':
        i += 1
        j = i
        while j < len(body) and body[j].isdigit():
            j += 1
        precision = int(body[i:j])
        i = j

    conv = body[i:i+1]

    # Now handle based on conversion type
    if conv == 's':
        # String formatting
        s_val = str(v)
        if precision is not None:
            s_val = s_val[:precision]
        if width is not None:
            if '-' in flags:
                result = s_val.ljust(width)
            else:
                result = s_val.rjust(width)
        else:
            result = s_val
        return result

    elif conv == 'c':
        ch = chr(v)
        if width is not None:
            if '-' in flags:
                result = ch.ljust(width)
            else:
                result = ch.rjust(width)
        else:
            result = ch
        return result

    else:
        # Integer conversions: d, i, u, x, X, o
        # Precision on integer conversions is "minimum digits" - this is what gets refused.
        # We need to compute the result the same way Python does.

        n = v

        if conv in ('d', 'i', 'u'):
            # Decimal representation
            if n < 0:
                sign = '-'
                digits = str(-n)
            else:
                sign = ''
                digits = str(n)

            # Apply precision: minimum number of digits (pad with zeros)
            if precision is not None and len(digits) < precision:
                digits = '0' * (precision - len(digits)) + digits

            # Determine if we need a sign
            if '+' in flags and n >= 0:
                sign = '+'
            elif ' ' in flags and n >= 0:
                sign = ' '

            # Zero-padding
            if '0' in flags and width is not None:
                # Total width includes sign
                total_needed = width - len(sign)
                if len(digits) < total_needed:
                    digits = '0' * (total_needed - len(digits)) + digits
                result = sign + digits
            else:
                result = sign + digits
                if width is not None:
                    if '-' in flags:
                        result = result.ljust(width)
                    else:
                        result = result.rjust(width)
            return result

        elif conv in ('x', 'X', 'o'):
            if n < 0:
                # Negative hex/octal
                if conv == 'x':
                    digits = format(-n, 'x')
                    prefix = '-0x' if '#' in flags else '-'
                elif conv == 'X':
                    digits = format(-n, 'X')
                    prefix = '-0X' if '#' in flags else '-'
                else:
                    digits = format(-n, 'o')
                    prefix = '-0o' if '#' in flags else '-'

                if precision is not None and len(digits) < precision:
                    digits = '0' * (precision - len(digits)) + digits

                body_str = prefix + digits

                if '0' in flags and width is not None:
                    total_needed = width - len(prefix)
                    if len(digits) < total_needed:
                        digits = '0' * (total_needed - len(digits)) + digits
                    result = prefix + digits
                else:
                    result = body_str
                    if width is not None:
                        if '-' in flags:
                            result = result.ljust(width)
                        else:
                            result = result.rjust(width)
                return result
            else:
                if conv == 'x':
                    digits = format(n, 'x')
                    prefix = '0x' if '#' in flags else ''
                elif conv == 'X':
                    digits = format(n, 'X')
                    prefix = '0X' if '#' in flags else ''
                else:
                    digits = format(n, 'o')
                    prefix = '0o' if '#' in flags else ''

                if precision is not None and len(digits) < precision:
                    digits = '0' * (precision - len(digits)) + digits

                body_str = prefix + digits

                if '0' in flags and width is not None:
                    total_needed = width - len(prefix)
                    if len(digits) < total_needed:
                        digits = '0' * (total_needed - len(digits)) + digits
                    result = prefix + digits
                else:
                    result = body_str
                    if width is not None:
                        if '-' in flags:
                            result = result.ljust(width)
                        else:
                            result = result.rjust(width)
                return result

        else:
            raise ValueError("unknown conversion: " + conv)


