def _my_repr(s):
    if not s:
        return "''"
    out = []
    for c in s:
        o = ord(c)
        if o < 32 or o > 126:
            # Non-printable ASCII control char or non-ASCII: use \xNN or \uNNNN / \UNNNNNNNN
            if o < 256:
                out.append("\\x" + format(o, "02x"))
            elif o < 0x10000:
                out.append("\\u" + format(o, "04x"))
            else:
                out.append("\\U" + format(o, "08x"))
        else:
            if c == "'":
                out.append("'")
            elif c == "\\":
                out.append("\\")
            else:
                out.append(c)
    return "'" + "".join(out) + "'"

