     "٠١","１０","٣","১২3","2147483648","-9223372036854775808","9223372036854775807"]

def safe_repr(s):
    # Mimic CPython's repr for strings containing only printable ASCII or requiring escapes
    # For our purposes, we need to handle:
    # - Regular printable ASCII (print as-is)
    # - Single quote: ' -> \'
    # - Double quote: " -> \" (but we use single quotes for the outer, so only escape single)
    # - Backslash: \ -> \\
    # - Non-printable ASCII: use \xNN escape
    # - Non-ASCII: use \uNNNN escape
    # CPython uses single quotes unless the string contains a single quote but no double quote
    result = []
    has_single = False
    has_double = False
    for c in s:
        if c == "'":
            has_single = True
        elif c == '"':
            has_double = True

    # Choose quote style: prefer single unless it contains single but not double
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    for c in s:
        code = ord(c)
        if quote == "'" and c == "'":
            result.append("\\'")
        elif quote == '"' and c == '"':
            result.append('\\"')
        elif c == "\\":
            result.append("\\\\")
        elif 32 <= code < 127:
            result.append(c)
        elif code < 127:
            result.append("\\x%02x" % code)
        else:
            result.append("\\u%04x" % code)

    return quote + "".join(result) + quote

for i,s in enumerate(S):
    if any(ord(c)>126 for c in s): print(i, safe_repr(s), [hex(ord(c)) for c in s])

