     "٠١","１０","٣","১২3","2147483648","-9223372036854775808","9223372036854775807"]

def custom_repr(s):
    if not s:
        return "''"
    # Determine if we use single or double quotes
    has_single = "'" in s
    has_double = '"' in s
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"
    result = [quote]
    for c in s:
        code = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif quote == "'" and c == "'":
            result.append("\\'")
        elif quote == '"' and c == '"':
            result.append('\\"')
        elif c == '\n':
            result.append('\\n')
        elif c == '\r':
            result.append('\\r')
        elif c == '\t':
            result.append('\\t')
        elif 32 <= code < 127:
            result.append(c)
        else:
            result.append('\\u%04x' % code)
    result.append(quote)
    return ''.join(result)

for i,s in enumerate(S):
    if any(ord(c)>126 for c in s):
        print(i, custom_repr(s), [hex(ord(c)) for c in s])

