        self.stdin_sample = stdin_sample

    @classmethod
    def from_obj(cls, obj):
        return cls(
            id=obj["id"],
            program=obj["program"],
            first_seen=obj["first_seen"],
            count=obj.get("count", 0),
            model=obj.get("model"),
            stdin_sample=obj.get("stdin_sample"),
        )

    def to_obj(self):
        d = {
            "id": self.id,
            "program": self.program,
            "count": self.count,
            "first_seen": self.first_seen,
        }
        if self.model is not None:
            d["model"] = self.model
        if self.stdin_sample is not None:
            d["stdin_sample"] = self.stdin_sample
        return d


def _rank(e):
    return (e.count, e.first_seen)


def merge(groups):
    # Merge a list of lists of Entries; return list of merged Entries.
    # For each unique id, pick the entry with highest rank (count, first_seen),
    # breaking ties by taking the first occurrence in the flattened order.
    seen = {}
    order = []
    for group in groups:
        for e in group:
            if e.id not in seen:
                seen[e.id] = e
                order.append(e.id)
            else:
                cur = seen[e.id]
                if _rank(e) > _rank(cur):
                    seen[e.id] = e
    return [seen[i] for i in order]


