            # naively cut at '#' not inside quotes
            in_str = False
            quote_char = ''
            out = []
            i = 0
            while i < len(line):
                ch = line[i]
                if in_str:
                    out.append(ch)
                    if ch == quote_char:
                        in_str = False
                else:
                    if ch in ('"', "'"):
                        in_str = True
                        quote_char = ch
                        out.append(ch)
                    elif ch == '#':
                        break
                    else:
                        out.append(ch)
                i += 1
            lines.append("".join(out))
        code_only = "\n".join(lines)
        if "random.seed(" in code_only:
            return True
    # getattr form
    if "getattr(random, 'seed')" in p or "getattr(random,'seed')" in p:
        lines = []
        for line in p.split("\n"):
            in_str = False
            quote_char = ''
            out = []
            i = 0
            while i < len(line):
                ch = line[i]
                if in_str:
                    out.append(ch)
                    if ch == quote_char:
