                i += 1
            lines.append("".join(out))
        code_only = "\n".join(lines)
        if "getattr(random, 'seed')" in code_only or "getattr(random,'seed')" in code_only:
            return True
    # alias form: s = random.seed ; s(...)
    if "= random.seed" in p:
        lines = []
        for line in p.split("\n"):
            in_str = False
            quote_char = ''
            out = []
            i = 0
            while i < len(line):
