                        quote_char = ch
                        out.append(ch)
                    elif ch == '#':
                        break
                    else:
                        out.append(ch)
                i += 1
            lines.append("".join(out))
        code_only = "\n".join(lines)
        if "= random.seed" in code_only:
            return True
    return False


def _is_run_specific(program):
    """A run-specific program is one whose output depends on the particular run
    (e.g., unseeded random, time-based seeds, pid-based seeds)."""
    p = program
    if not _is_seeded_stream(p):
        return True
    # Seeded with a constant -> not run-specific
    # Seeded with time.time() or os.getpid() -> run-specific
    if "time.time()" in p and "seed" in p:
        return True
    if "os.getpid()" in p and "seed" in p:
        return True
    return False


def _is_nondeterministic(program):
    """Nondeterministic if it uses unseeded random or runtime-varying seeds."""
    p = program
    if "random.random()" not in p and "random.seed" not in p:
        return False
    # If seeded with a fixed constant, deterministic
    if _is_seeded_stream(p):
        if "time.time()" in p:
            return True
        if "os.getpid()" in p:
            return True
        return False
    return True


