    if isnan(x) or isnan(y) or isinf(x):
        return float('nan')
    if isinf(y):
        return x
    if y == 0.0:
        return float('nan')
    q = x / y
    if isnan(q) or isinf(q):
        # Overflow case: result is x itself (per IEEE 754 fmod)
        return x
    r = x - q * y
    if r == 0.0:
        return copysign(0.0, x)
    return r

