def _eval_expr(expr):
    # Parse the expression and evaluate it without using eval()
    expr = expr.strip()

    # Handle re.sub and re.subn and re.split calls
    if expr.startswith('re.sub(') or expr.startswith('re.subn(') or expr.startswith('re.split('):
        return _eval_re_call(expr)

    raise ValueError("Unsupported expression: " + expr)


def _eval_re_call(expr):
    # Extract the function name and arguments
    if expr.startswith('re.subn('):
        func_name = 're.subn'
    elif expr.startswith('re.split('):
        func_name = 're.split'
    else:
        func_name = 're.sub'

    # Find the matching closing parenthesis
    args_str = _extract_args(expr, len(func_name))
    args = _parse_args(args_str)

    if func_name == 're.sub':
        return re.sub(*args)
    elif func_name == 're.subn':
        return re.subn(*args)
    elif func_name == 're.split':
        return re.split(*args)


def _extract_args(expr, start):
    # Extract the string between the opening and closing parenthesis
    depth = 0
    i = start
    in_string = None
    while i < len(expr):
        c = expr[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            if c == in_string:
                in_string = None
        else:
            if c in ("'", '"'):
                in_string = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0:
                    return expr[start+1:i]
        i += 1
    raise ValueError("Unbalanced parentheses")


def _parse_args(args_str):
    # Parse comma-separated arguments, respecting strings
    args = []
    current = []
    depth = 0
    in_string = None
    i = 0
    while i < len(args_str):
        c = args_str[i]
        if in_string:
            current.append(c)
            if c == '\\':
                if i + 1 < len(args_str):
                    current.append(args_str[i+1])
                    i += 2
                    continue
            elif c == in_string:
                in_string = None
        else:
            if c in ("'", '"'):
                in_string = c
                current.append(c)
            elif c == '(':
                depth += 1
                current.append(c)
            elif c == ')':
                depth -= 1
                current.append(c)
            elif c == ',' and depth == 0:
                arg_str = ''.join(current).strip()
                args.append(_parse_value(arg_str))
                current = []
                i += 1
                continue
            else:
                current.append(c)
        i += 1

    if current:
        arg_str = ''.join(current).strip()
        args.append(_parse_value(arg_str))

    return args


def _parse_value(s):
    # Parse a single value from its string representation
    s = s.strip()

    # Check if it's a string literal
    if len(s) >= 2 and ((s[0] == "'" and s[-1] == "'") or (s[0] == '"' and s[-1] == '"')):
        return _parse_string_literal(s)

    # Check if it's a lambda
    if s.startswith('lambda'):
        return _parse_lambda(s)

    # Check for integers
    try:
        return int(s)
    except ValueError:
        pass

    # Check for other literals
    if s == 'True':
        return True
    elif s == 'False':
        return False
    elif s == 'None':
        return None

    raise ValueError("Cannot parse value: " + s)


def _parse_string_literal(s):
    # Parse a Python string literal into its value
    quote = s[0]
    content = s[1:-1]

    result = []
    i = 0
    while i < len(content):
        c = content[i]
        if c == '\\' and i + 1 < len(content):
            nxt = content[i+1]
            if nxt == 'n':
                result.append('\n')
            elif nxt == 't':
                result.append('\t')
            elif nxt == 'r':
                result.append('\r')
            elif nxt == '\\':
                result.append('\\')
            elif nxt == quote:
                result.append(quote)
            elif nxt == '0':
                result.append('\0')
            elif nxt == 'x':
                hex_str = content[i+2:i+4]
                result.append(chr(int(hex_str, 16)))
                i += 4
                continue
            else:
                result.append('\\')
                result.append(nxt)
            i += 2
        else:
            result.append(c)
            i += 1

    return ''.join(result)


def _parse_lambda(s):
    # Parse a lambda expression - for our specific case: lambda m: m.group(0).upper()
    if s == 'lambda m: m.group(0).upper()':
        def lam(m):
            return m.group(0).upper()
        return lam
    raise ValueError("Unsupported lambda: " + s)


