def do_eval(expr):
    # Supported forms only
    # re.findall(pattern, string)
    # re.findall(pattern, string, flags)
    # re.sub(pattern, repl, string)
    # re.sub(pattern, repl, string, count)
    # re.sub(pattern, repl, string, count, flags)
    # re.split(pattern, string)
    # re.escape(obj)
    # re.compile(pattern) -- but not used in our test cases directly outside findall

    # Parse the expression
    expr_stripped = expr.strip()
    if not (expr_stripped.startswith('re.') and expr_stripped.endswith(')')):
        raise ValueError("unsupported expression")

    inner = expr_stripped[3:-1]  # remove 're.' and ')'

    # Split on top-level commas
    parts = split_top_level(inner)

    if len(parts) == 0:
        raise ValueError("empty")

    func_name = parts[0].strip()
    args = [p.strip() for p in parts[1:]]

    if func_name == 'findall':
        if len(args) == 2:
            return re.findall(eval_arg(args[0]), eval_arg(args[1]))
        elif len(args) == 3:
            return re.findall(eval_arg(args[0]), eval_arg(args[1]), eval_arg(args[2]))
        else:
            raise TypeError("wrong number of args")
    elif func_name == 'sub':
        if len(args) == 3:
            return re.sub(eval_arg(args[0]), eval_arg(args[1]), eval_arg(args[2]))
        elif len(args) == 4:
            return re.sub(eval_arg(args[0]), eval_arg(args[1]), eval_arg(args[2]), eval_arg(args[3]))
        elif len(args) == 5:
            return re.sub(eval_arg(args[0]), eval_arg(args[1]), eval_arg(args[2]), eval_arg(args[3]), eval_arg(args[4]))
        else:
            raise TypeError("wrong number of args")
    elif func_name == 'split':
        if len(args) == 2:
            return re.split(eval_arg(args[0]), eval_arg(args[1]))
        elif len(args) == 3:
            return re.split(eval_arg(args[0]), eval_arg(args[1]), eval_arg(args[2]))
        else:
            raise TypeError("wrong number of args")
    elif func_name == 'escape':
        if len(args) == 1:
            return re.escape(eval_arg(args[0]))
        else:
            raise TypeError("wrong number of args")
    else:
        raise AttributeError("no attribute '%s'" % func_name)

def split_top_level(s):
    parts = []
    depth = 0
    in_str = False
    str_char = ''
    i = 0
    while i < len(s):
        c = s[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            elif c == str_char:
                in_str = False
            i += 1
            continue
        else:
            if c in ("'", '"'):
                in_str = True
                str_char = c
                i += 1
                continue
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            elif c == ',' and depth == 0:
                parts.append(s[parts_start if 'parts_start' in dir() else 0:i])
                # Actually need to track start
                break
            i += 1

    # Redo properly
    parts = []
    start = 0
    depth = 0
    in_str = False
    str_char = ''
    i = 0
    while i < len(s):
        c = s[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            elif c == str_char:
                in_str = False
            i += 1
            continue
        else:
            if c in ("'", '"'):
                in_str = True
                str_char = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            elif c == ',' and depth == 0:
                parts.append(s[start:i])
                start = i + 1
            i += 1
    parts.append(s[start:])
    return parts

def eval_arg(s):
    s = s.strip()
    if s.startswith("r'") or s.startswith('r"'):
        quote = s[1]
        body = s[2:-1]
        return body
    elif s.startswith("'") and s.endswith("'") and len(s) >= 2:
        body = s[1:-1]
        # Handle escape sequences
        result = []
        i = 0
        while i < len(body):
            if body[i] == '\\' and i + 1 < len(body):
                nxt = body[i+1]
                if nxt == 'n': result.append('\n'); i += 2
                elif nxt == 't': result.append('\t'); i += 2
                elif nxt == 'r': result.append('\r'); i += 2
                elif nxt == '\\': result.append('\\'); i += 2
                elif nxt == "'": result.append("'"); i += 2
                elif nxt == '"': result.append('"'); i += 2
                else: result.append(body[i:i+2]); i += 2
            else:
                result.append(body[i]); i += 1
        return ''.join(result)
    elif s.startswith('"') and s.endswith('"') and len(s) >= 2:
        body = s[1:-1]
        result = []
        i = 0
        while i < len(body):
            if body[i] == '\\' and i + 1 < len(body):
                nxt = body[i+1]
                if nxt == 'n': result.append('\n'); i += 2
                elif nxt == 't': result.append('\t'); i += 2
                elif nxt == 'r': result.append('\r'); i += 2
                elif nxt == '\\': result.append('\\'); i += 2
                elif nxt == "'": result.append("'"); i += 2
                elif nxt == '"': result.append('"'); i += 2
                else: result.append(body[i:i+2]); i += 2
            else:
                result.append(body[i]); i += 1
        return ''.join(result)
    elif s == 'b"abc"' or s.startswith('b"'):
        quote = s[2]
        body = s[3:-1]
        return body.encode('utf-8')
    elif s.startswith("b'") :
        body = s[2:-1]
        return body.encode('utf-8')
    elif s == 're.I':
        return re.I
    elif s == 're.M':
        return re.M
    elif s == 're.S':
        return re.S
    elif s.startswith('re.compile('):
        inner = s[len('re.compile('):-1]
        parts = split_top_level(inner)
        pats = [p.strip() for p in parts]
        if len(pats) == 1:
            return re.compile(eval_arg(pats[0]))
        elif len(pats) == 2:
            return re.compile(eval_arg(pats[0]), eval_arg(pats[1]))
        else:
            raise ValueError("bad compile")
    elif s.isdigit():
        return int(s)
    else:
        # Maybe it's a name like re.I already handled
        raise NameError("name '%s' is not defined" % s)

