def _b64decode(s, validate=False):
    if isinstance(s, str):
        s = s.encode('ascii')
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("argument should be a bytes-like object or ASCII-only string, not %r" % type(s).__name__)
    s = bytes(s)
    if validate:
        i = 0
        n = len(s)
        while i < n:
            c = s[i:i+1]
            if c == b'\n':
                i += 1
                continue
            if not (b'A' <= c <= b'Z') and not (b'a' <= c <= b'z') and not (b'0' <= c <= b'9') and c != b'+' and c != b'/' and c != b'=':
                import binascii
                raise binascii.Error("Invalid base64-encoded string: number of data characters (1) cannot be 1 more than a multiple of 4")
            i += 1
    # strip whitespace
    t = b''.join(s.split())
    if not t:
        return b''
    # validate that only valid b64 chars (plus =) remain
    for b in t:
        ch = bytes([b])
        if not (b'A' <= ch <= b'Z') and not (b'a' <= ch <= b'z') and not (b'0' <= ch <= b'9') and ch != b'+' and ch != b'/' and ch != b'=':
            import binascii
            raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % len(t))
    # padding check
    pad = 0
    while pad < len(t) and t[-1-pad:] == b'=':
        pad += 1
    # all '=' must be at end
    if b'=' in t[:-pad]:
        import binascii
        raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % (len(t)-pad))
    data_len = len(t) - pad
    if pad > 2 or data_len == 0:
        import binascii
        raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_len)
    if data_len % 4 == 1:
        import binascii
        raise binascii.Error("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_len)
    # decode
    vals = []
    for b in t:
        c = bytes([b])
        if b'0' <= c <= b'9':
            vals.append(ord(c) - 48)
        elif b'A' <= c <= b'Z':
            vals.append(ord(c) - 55)
        elif b'a' <= c <= b'z':
            vals.append(ord(c) - 87)
        elif c == b'+':
            vals.append(62)
        elif c == b'/':
            vals.append(63)
        else:
            vals.append(0)
    out = bytearray()
    i = 0
    while i < len(vals):
        if i + 4 <= len(vals):
            v = vals[i] << 18 | vals[i+1] << 12 | vals[i+2] << 6 | vals[i+3]
            out.append((v >> 16) & 0xff)
            out.append((v >> 8) & 0xff)
            out.append(v & 0xff)
            i += 4
        elif i + 3 == len(vals):
            v = vals[i] << 18 | vals[i+1] << 12 | vals[i+2] << 6
            out.append((v >> 16) & 0xff)
            out.append((v >> 8) & 0xff)
            i += 3
        elif i + 2 == len(vals):
            v = vals[i] << 18 | vals[i+1] << 12
            out.append((v >> 16) & 0xff)
            i += 2
    return bytes(out)

def _b64encode(s, altchars=None):
    if isinstance(s, str):
        s = s.encode('utf-8')
    if not isinstance(s, (bytes, bytearray, memoryview)):
