    elif v < 52:
        return chr(97 + v - 26)
    elif v < 62:
        return chr(48 + v - 52)
    elif v == 62:
        return '+'
    else:
        return '/'

def urlsafe_b64decode(s):
    return _b64decode(s.replace(b'-', b'+').replace(b'_', b'/'))

