    B = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    out = []
    i = 0
    n = len(data)
    while i + 3 <= n:
        chunk = (data[i] << 16) | (data[i+1] << 8) | data[i+2]
        out.append(B[(chunk >> 18) & 0x3F])
        out.append(B[(chunk >> 12) & 0x3F])
        out.append(B[(chunk >> 6) & 0x3F])
        out.append(B[chunk & 0x3F])
        i += 3
    rem = n - i
    if rem == 1:
        c = data[i]
