    return bytes(b for b in data if b not in b'\t\n\r\f\v ')

def _decode(data, urlsafe=False):
    B = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
    alpha = A if urlsafe else B
    val = {}
    for idx, ch in enumerate(alpha):
        val[ch] = idx
    s = _clean(data).decode('latin-1')
    if s.count('=') > 2:
        raise Exception('binascii.Error: Invalid base64-encoded string')
    if '=' in s[:-2]:
        raise Exception('binascii.Error: Invalid base64-encoded string: number of data characters (X) cannot be 1 more than a multiple of 4'.replace('X', str(len(s))))
    if len(s) % 4 != 0:
        pad = 4 - (len(s) % 4)
        s += '=' * pad
    out = bytearray()
    i = 0
    while i < len(s):
        quad = s[i:i+4]
        # count padding
        n_eq = 0
        for ch in quad:
            if ch == '=':
                n_eq += 1
            else:
                break
        # first four chars of quad should be non-= except trailing
        vals = []
        for ch in quad:
            if ch == '=':
                vals.append(0)
            elif ch in val:
                vals.append(val[ch])
            else:
                raise Exception('binascii.Error: Invalid base64-encoded string: bad character')
        byte0 = (vals[0] << 2) | (vals[1] >> 4)
        byte1 = ((vals[1] & 0xF) << 4) | (vals[2] >> 2)
        byte2 = ((vals[2] & 0x3) << 6) | vals[3]
        out.append(byte0)
        if n_eq < 2:
            out.append(byte1)
        if n_eq < 1:
            out.append(byte2)
        i += 4
    return bytes(out)

def b64decode(s, validate=False):
    return _decode(s, urlsafe=False)

def urlsafe_b64decode(s):
    return _decode(s, urlsafe=True)

