import csv, io

QUOTINGS = [0, 1, 2, 3]
ESCAPES = [None, "\\", "!"]
DQ = [True, False]
DELIMS = [",", ";"]
QCHARS = ['"', "'"]
TERMS = ["\r\n", "\n", "|"]
ROWS = [
    ["a", "b"], [""], ["", ""], [], [None], ["a,b"], ["a;b"], ['say "hi"'],
    ["a'b"], ["a\\b"], ["a!b"], ["a\nb"], ["a\rb"], ["a|b"], ["a b", " "],
    [1, 2.5, True, None, "x"], [1e22, 0.1 + 0.2, 2.0], [1, "1", 1.0], ["", 0],
    [b"x", [1, 2]], ['"'], ["\\"], ["!"], [",;\"'\\!\r\n|"],
]
READS = [
    ["a,b,c\n", "1,2,3\n"], ['"q,q",2,"say ""hi"""\n', "\n", "last"],
    ['"a\n', 'b",c\n'], ["1,\"2\",\n", "3.5,4\n"], ["a,b\n"], ["abc\n"],
    ['a\\,b,c\n'], ['a!,b,c\n'], ['"a",b\n'], ['a, b, "c"\n'], ['"a"x,b\n'],
    ['"a\n'], ['"a""b",c\n'], ['"a\\"b",c\n'], ["a,b\r\n", "c,d\r\n"],
    ["a;b\n"], ["a'b',c\n"], ["'a','b,b'\n"], ["\n", "\n", "a\n"],
    ["a\\\n", "b\n"], ["a\\"], ["a,b"], ["a|b\n"], ["a,,b\n"], [",\n"],
    ["  a , b\n"], ["a\\\\,b\n"], ['"1","2"\n'], ["1,2\n"], ["-3.5e2,x\n"],
]

def call(fn):
    try:
        return "ok " + repr(fn())
    except Exception as e:
        return "err " + type(e).__name__ + " " + str(e)

n = 0
for q in QUOTINGS:
    for e in ESCAPES:
        for dq in DQ:
            for dl in DELIMS:
                for qc in QCHARS:
                    for lt in TERMS:
                        for i in range(len(ROWS)):
                            row = ROWS[i]
                            def mk(row=row, q=q, e=e, dq=dq, dl=dl, qc=qc, lt=lt):
                                o = io.StringIO()
                                w = csv.writer(o, quoting=q, escapechar=e,
                                               doublequote=dq, delimiter=dl,
                                               quotechar=qc, lineterminator=lt)
                                r = w.writerow(row)
                                return (o.getvalue(), r)
                            print("w", q, e, dq, dl, qc, repr(lt), i, call(mk))
                            n += 1
for q in QUOTINGS:
    for e in ESCAPES:
        for dq in DQ:
            for dl in DELIMS:
                for qc in QCHARS:
                    for st in (False, True):
                        for si in (False, True):
                            for i in range(len(READS)):
                                lines = READS[i]
                                def mk(lines=lines, q=q, e=e, dq=dq, dl=dl,
                                       qc=qc, st=st, si=si):
                                    rd = csv.reader(iter(lines), quoting=q,
                                                    escapechar=e, doublequote=dq,
                                                    delimiter=dl, quotechar=qc,
                                                    strict=st, skipinitialspace=si)
                                    rows = []
                                    for row in rd:
